import api from './api';

export const getOwnProfile = async () => {
  try {
    const response = await api.get('/self/me');
    return response.data;
  } catch (error) {
    throw error.response?.data?.message || 'Failed to fetch profile';
  }
};

export const updateOwnProfile = async (profileData) => {
  try {
    const response = await api.put('/self/me', profileData);
    return response.data;
  } catch (error) {
    throw error.response?.data?.message || 'Failed to update profile';
  }
};

export const getAllEmployeesForHR = async () => {
  try {
    const response = await api.get('/hr/employees');
    return response.data;
  } catch (error) {
    throw error.response?.data?.message || 'Failed to fetch employees';
  }
};

export const getEmployeeByIdForHR = async (id) => {
  try {
    const response = await api.get(`/hr/employees/${id}`);
    return response.data;
  } catch (error) {
    throw error.response?.data?.message || 'Failed to fetch employee';
  }
};

export const getAllEmployeesForOthers = async () => {
  try {
    const response = await api.get('/others/employees');
    return response.data;
  } catch (error) {
    throw error.response?.data?.message || 'Failed to fetch employees';
  }
};

export const getEmployeeByIdForOthers = async (id) => {
  try {
    const response = await api.get(`/others/employees/${id}`);
    return response.data;
  } catch (error) {
    throw error.response?.data?.message || 'Failed to fetch employee';
  }
};
